// UpdateCompletionOffsetAndHeapEntry atomically advances the completion offset and clears the
// pending heap entry for an attached function. The WHERE guard on completion_offset ensures the
// offset can only move forwards: if newOffset is not strictly greater than the currently stored
// completion_offset, no rows are affected and common.ErrAttachedFunctionOffsetWouldRegress is returned.
func (s *attachedFunctionDb) UpdateCompletionOffsetAndHeapEntry(id uuid.UUID, collectionID string, newOffset int64) error {
	result := s.db.Model(&dbmodel.AttachedFunction{}).
		Where("id = ?", id).
		Where("input_collection_id = ?", collectionID).
		Where("completion_offset < ?", newOffset).
		Updates(map[string]interface{}{
			"completion_offset":  newOffset,
			"heap_entry_pending": false,
			"updated_at":         gorm.Expr("NOW()"),
		})

	if result.Error != nil {
		log.Error("update completion offset and heap entry failed", zap.Error(result.Error))
		return result.Error
	}

	if result.RowsAffected == 0 {
		log.Error("update completion offset and heap entry: offset would regress",
			zap.String("id", id.String()),
			zap.Int64("new_offset", newOffset))
		return common.ErrAttachedFunctionOffsetWouldRegress
	}

	return nil
}

// UpdateHeapEntryPending sets the heap_entry_pending flag for an attached function.
func (s *attachedFunctionDb) UpdateHeapEntryPending(id uuid.UUID, pending bool) error {
	result := s.db.Model(&dbmodel.AttachedFunction{}).
		Where("id = ?", id).
		Updates(map[string]interface{}{
			"heap_entry_pending": pending,
			"updated_at":         gorm.Expr("NOW()"),
		})

	if result.Error != nil {
		log.Error("update heap entry pending failed", zap.Error(result.Error))
		return result.Error
	}

	return nil
}

