			"name":       gorm.Expr("CONCAT('_deleted_', name, '_', id::text)"),
			"is_deleted": true,
			"updated_at": gorm.Expr("NOW()"),
		})

	if result.Error != nil {
		log.Error("SoftDelete failed", zap.Error(result.Error))
		return result.Error
	}

	// If no rows were affected, attached function was not found (or already deleted)
